CREATE TABLE evidence_notes(note_id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites,source_id TEXT REFERENCES sources,topic TEXT NOT NULL,locator TEXT,detail TEXT NOT NULL,evidence_class TEXT NOT NULL,archive_status TEXT NOT NULL,created_on TEXT NOT NULL);
CREATE VIEW v_site_dossier AS SELECT s.*, (SELECT count(*) FROM wastewater w WHERE w.site_id=s.site_id) AS water_rows,(SELECT count(*) FROM water_metrics m WHERE m.site_id=s.site_id) AS metric_rows,(SELECT count(*) FROM capacity c WHERE c.site_id=s.site_id) AS capacity_rows,(SELECT count(*) FROM site_sources a JOIN sources e USING(source_id) WHERE a.site_id=s.site_id AND NULLIF(e.url,'') IS NOT NULL) AS linked_urls,(SELECT count(*) FROM evidence_notes d WHERE d.site_id=s.site_id) AS note_rows FROM sites s;
CREATE VIEW v_evidence_detail AS SELECT d.*,s.name,e.title,e.url,e.document_date,e.scope FROM evidence_notes d JOIN sites s USING(site_id) LEFT JOIN sources e USING(source_id);
CREATE VIEW v_water_dossier AS SELECT s.name,s.province,s.city,w.*,e.title,e.url,e.document_date,e.scope AS source_scope FROM wastewater w JOIN sites s USING(site_id) LEFT JOIN sources e USING(source_id);
COMMIT;
