INSERT INTO evidence_notes SELECT 'D-W-'||w.water_id,w.site_id,w.source_id,'废水历史/本轮结构化摘录',e.scope,COALESCE(w.stream,'')||'；阶段：'||COALESCE(w.stage,'未知')||'；工艺：'||COALESCE(w.process,'未知')||'；流量：'||COALESCE(CAST(w.flow AS TEXT),'未知')||' '||COALESCE(w.flow_unit,'')||'；口径：'||COALESCE(w.flow_basis,'')||'；污染物：'||COALESCE(w.pollutants,'')||'；去向：'||COALESCE(w.destination,'未知')||'；残余物：'||COALESCE(w.residuals,'')||'；备注：'||COALESCE(w.notes,''),CASE WHEN w.confidence IN ('WEB_PRIMARY','WEB_COMPANY','WEB_SECONDARY','MODEL_UNVERIFIED','INFERRED') THEN w.confidence ELSE 'LEGACY_PENDING' END,'结构化内容保全，非原文全文','2026-11-27' FROM wastewater w LEFT JOIN sources e USING(source_id);
INSERT INTO evidence_notes SELECT 'D-S-'||site_id,site_id,NULL,'工厂历史摘要',NULL,water_summary,'LEGACY_PENDING','原有摘要保全，非新增事实','2026-11-27' FROM sites WHERE NULLIF(water_summary,'') IS NOT NULL;
INSERT INTO evidence_notes VALUES ('D-N-01-CN0038','CN0038','W05S01','审批细节','三（三）2及四','工程总投资3.53亿元；设计新增总量COD 0.6802t/a、氨氮0.034t/a；适用DB41/1066-2020表1及园区接管标准。生产水与冷却、纯水排水不同路径。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
INSERT INTO evidence_notes VALUES ('D-N-02-CN0213','CN0213','W05S02','设计与辅助设施','项目概况及废水条款','项目总投资2142.97万元，环保投资100万元（全项目）；运行300天7200小时；现有事故池700m³；污水站废气另有酸碱吸收，不能当成污水工艺。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
INSERT INTO evidence_notes VALUES ('D-N-03-CN0187','CN0187','W05S03','项目边界及盐回收','项目概况、排水条款','总投资33800万元、环保3875万元；25000吨危废含HW50 17100吨，其他7900吨；湿法车间盐回收是单股设计，生活、公用水仍纳管。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
INSERT INTO evidence_notes VALUES ('D-N-04-CN0214','CN0214','W05S04','完整水量口径','印刷92–93页','循环水540t/h为循环量而非排水；排污12.96t/d；纯水1500t/a，浓水1000t/a；初期雨水原审批已计不重复。截图失败；正文标题与搜索标题冲突，后续查审批原件。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
INSERT INTO evidence_notes VALUES ('D-N-05-CN0214','CN0214','W05S05','生产边界','安全评价公开','新催化剂500吨/年及再生1000吨/年；子公司福建东莹历史项目制备20.3吨，约30批/年、15吨/批再生；不能把母子两地废水照搬。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
INSERT INTO evidence_notes VALUES ('D-N-07-CN0216','CN0216','W05S07','既有与缓建分界','2.2.2、2.3.1、3.1.9.4','2018批复3.8万吨，2021年4月3.7万吨验收；贵金属0.1万吨缓建。既有有色车间清洗分两类回用；废气水中和沉淀后槽车外送；技改后脱油炉排水计划进站。2021历史监测见指标表。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
INSERT INTO evidence_notes VALUES ('D-N-08-CN0217','CN0217','W05S08','源强及证据缺口','3.1.5、废水表','初期雨水0.68万t/a，单独口径；生活0.179万t/a，化粪池后厂站；不含雨水合计0.437万t/a；水处理单元未从正文确认；截图超限。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
INSERT INTO evidence_notes VALUES ('D-N-16-CN0220','CN0220','W05S16','混合厂站高浓分流','拟审批废水条款','废酸浓缩水多效缓冲与ZVI-OR；中和高浓水破酚、预分离、ZVI-OR、三效蒸发；脱水废水苯胺类回收；再与低浓水进入梯级生化。催化剂活化废水具体支路未指明。','WEB_PRIMARY','改写摘录；网页/页码可追溯，非原件全文','2026-11-27');
